export function parseArguments(argv, programName, stdout, stderr) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      write(stdout, helpText(programName));
      return { ok: false, exitCode: 0 };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (!token.startsWith('--')) {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const specification = OPTION_INDEX.get(optionName);

    if (!specification) {
      extras.push(token);
      continue;
    }

    let rawValue;

    if (equalsIndex !== -1) {
      rawValue = token.slice(equalsIndex + 1);
    } else {
      const nextToken = argv[index + 1];

      if (tokenNeedsValue(nextToken)) {
        return errorResult(programName, `argument ${optionName}: expected one argument`, stderr);
