      rawValue = nextToken;
      index += 1;
    }

    if (specification.type === 'int') {
      try {
        values[specification.name] = parsePythonStyleInt(rawValue);
      } catch (error) {
        return errorResult(programName, `argument ${optionName}: ${error.message}`, stderr);
      }
      continue;
    }

    values[specification.name] = rawValue;
  }

  const missing = ARGUMENT_SPECS
    .filter((spec) => values[spec.name] === undefined)
    .map((spec) => `--${spec.name}`);

  if (missing.length > 0) {
    return errorResult(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
      stderr,
    );
  }

  if (extras.length > 0) {
    return errorResult(programName, `unrecognized arguments: ${extras.join(' ')}`, stderr);
  }

  return { ok: true, values };
}

