import {
  ALPHABET_INDEX,
  ASCII_WHITESPACE_BYTES,
} from './alphabet.mjs';

export function ensureByteArray(value, label = 'value') {
  if (!Array.isArray(value)) {
    throw new TypeError(`${label} must be an array of byte values`);
  }

  return value.slice();
}

export function asciiStringToBytes(text) {
  const bytes = [];

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (codePoint > 0x7f) {
      throw new Error('base58 input must be ASCII');
    }

    bytes.push(codePoint);
  }

  return bytes;
}

export function asciiBytesToString(bytes) {
  let result = '';

  for (const byte of bytes) {
    result += String.fromCharCode(byte);
  }

  return result;
}

export function coerceAsciiInput(value) {
  if (typeof value === 'string') {
    return asciiStringToBytes(value);
  }

  return ensureByteArray(value);
}

export function rstripAsciiWhitespace(bytes) {
  let end = bytes.length;

  while (end > 0 && ASCII_WHITESPACE_BYTES.has(bytes[end - 1])) {
    end -= 1;
  }

  return bytes.slice(0, end);
}

export function bytesToBigInt(bytes) {
  let value = 0n;

  for (const byte of bytes) {
    value = (value << 8n) + BigInt(byte);
  }

  return value;
}

export function bigIntToBytes(value) {
  if (value === 0n) {
    return [];
  }

  let hex = value.toString(16);

  if (hex.length % 2 !== 0) {
    hex = `0${hex}`;
  }

  const bytes = [];

  for (let index = 0; index < hex.length; index += 2) {
    bytes.push(Number.parseInt(hex.slice(index, index + 2), 16));
  }

  return bytes;
}

export function getBase58Index(byte) {
  const character = String.fromCharCode(byte);
  const index = ALPHABET_INDEX.get(character);

  if (index === undefined) {
    throw new Error(`Invalid character '${character}'`);
  }

  return index;
}

export function concatBytes(...parts) {
  const result = [];

  for (const part of parts) {
    result.push(...part);
  }

  return result;
}

export function bytesEqual(left, right) {
  if (left.length !== right.length) {
    return false;
  }

  for (let index = 0; index < left.length; index += 1) {
    if (left[index] !== right[index]) {
      return false;
    }
  }

  return true;
}

