import {
  BASE58_BASE,
  BITCOIN_ALPHABET,
  LEADING_ZERO_BYTE,
} from './alphabet.mjs';
import {
  asciiStringToBytes,
  bigIntToBytes,
  bytesToBigInt,
  coerceAsciiInput,
  concatBytes,
  ensureByteArray,
  getBase58Index,
  rstripAsciiWhitespace,
} from './helpers.mjs';

function coerceBigInt(value) {
  if (typeof value === 'bigint') {
    return value;
  }

  if (typeof value === 'number' && Number.isInteger(value)) {
    return BigInt(value);
  }

  if (typeof value === 'string' && value.length > 0) {
    return BigInt(value);
  }

  throw new TypeError('value must be an integer');
}

export function b58encodeInt(value, defaultOne = true) {
  let remaining = coerceBigInt(value);

  if (remaining < 0n) {
    throw new RangeError('a negative integer cannot be encoded');
  }

  if (remaining === 0n) {
    return defaultOne ? [LEADING_ZERO_BYTE] : [];
  }

  let encoded = '';

  while (remaining > 0n) {
    const remainder = Number(remaining % BASE58_BASE);
    remaining /= BASE58_BASE;
    encoded = BITCOIN_ALPHABET[remainder] + encoded;
  }

  return asciiStringToBytes(encoded);
}

export function b58encode(value) {
  const bytes = ensureByteArray(value);
  let leadingZeroes = 0;

  while (leadingZeroes < bytes.length && bytes[leadingZeroes] === 0) {
    leadingZeroes += 1;
  }

  const encoded = b58encodeInt(bytesToBigInt(bytes), false);

  return concatBytes(
    new Array(leadingZeroes).fill(LEADING_ZERO_BYTE),
    encoded,
  );
}

export function b58decodeInt(value) {
  const input = rstripAsciiWhitespace(coerceAsciiInput(value));
  let decoded = 0n;

  for (const byte of input) {
    decoded = (decoded * BASE58_BASE) + BigInt(getBase58Index(byte));
  }

  return decoded;
}

export function b58decode(value) {
  const input = rstripAsciiWhitespace(coerceAsciiInput(value));
  let leadingZeroes = 0;

  while (leadingZeroes < input.length && input[leadingZeroes] === LEADING_ZERO_BYTE) {
    leadingZeroes += 1;
  }

  const decoded = b58decodeInt(input.slice(leadingZeroes));

  return concatBytes(
    new Array(leadingZeroes).fill(0),
    bigIntToBytes(decoded),
  );
}
